class MainActivity : ComponentActivity() {

    private val notificationPermissionLauncher = registerForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { /* User choice recorded; no further action needed. */ }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        requestNotificationPermissionIfNeeded()
        enableEdgeToEdge()
        setContent {
            ClawDroidTheme {
                val navController = rememberNavController()
                val wsClient: WebSocketClient = koinInject()

                // Observe setup_required state from server
                LaunchedEffect(Unit) {
                    wsClient.setupRequired.collect { required ->
                        if (required) {
                            val current = navController.currentDestination?.route
                            if (current != NavRoutes.SETUP) {
                                navController.navigate(NavRoutes.SETUP) {
                                    launchSingleTop = true
                                }
                            }
                        }
                    }
                }

                NavHost(navController = navController, startDestination = NavRoutes.CHAT) {
                    composable(NavRoutes.CHAT) {
                        ChatScreen(
                            onNavigateToSettings = { navController.navigate(NavRoutes.SETTINGS) },
                            onLaunchAssistant = { startActivity(Intent(this@MainActivity, AssistantActivity::class.java)) }
                        )
                    }
                    composable(NavRoutes.SETTINGS) {
                        SettingsScreen(
                            onNavigateBack = { navController.popBackStack() },
                            onNavigateToBackendSettings = { navController.navigate(NavRoutes.BACKEND_SETTINGS) },
                            onNavigateToAppSettings = { navController.navigate(NavRoutes.appSettings()) },
                            onExportDiagnostics = { navController.navigate(NavRoutes.DIAGNOSTICS) },
                            onNavigateToPermissions = { navController.navigate(NavRoutes.PERMISSIONS) },
                            onNavigateToOpenAi = { navController.navigate(NavRoutes.OPENAI) },
                            showAdvancedSettings = BuildConfig.FLAVOR != "embedded",
                            onLaunchAssistant = { startActivity(Intent(this@MainActivity, AssistantActivity::class.java)) },
                        )
                    }
                    composable(NavRoutes.DIAGNOSTICS) {
                        io.clawdroid.diagnostics.DiagnosticsExportScreen(onBack = { navController.popBackStack() })
                    }
                    composable(NavRoutes.PERMISSIONS) {
                        io.clawdroid.settings.PermissionHelpScreen(onNavigateBack = { navController.popBackStack() })
                    }
                    composable(NavRoutes.OPENAI) {
                        OpenAiSetupScreen(onConnected = { navController.popBackStack() }, onBack = { navController.popBackStack() }, onExport = { navController.navigate(NavRoutes.DIAGNOSTICS) })
                    }
                    navigation(
                        route = NavRoutes.BACKEND_SETTINGS,
                        startDestination = NavRoutes.BACKEND_SETTINGS_LIST,
                    ) {
                        composable(NavRoutes.BACKEND_SETTINGS_LIST) { entry ->
                            val parentEntry = remember(entry) {
                                navController.getBackStackEntry(NavRoutes.BACKEND_SETTINGS)
                            }
                            val viewModel: ConfigViewModel = koinViewModel(viewModelStoreOwner = parentEntry)
                            ConfigSectionListScreen(
                                onNavigateBack = { navController.popBackStack() },
                                onSectionSelected = { sectionKey ->
                                    navController.navigate("backend_settings/$sectionKey")
                                },
                                onNavigateToAppSettings = {
                                    navController.navigate(NavRoutes.appSettings(localOnly = true))
                                },
                                viewModel = viewModel,
                            )
                        }
                        composable(
                            NavRoutes.BACKEND_SETTINGS_SECTION,
                            arguments = listOf(navArgument("sectionKey") { type = NavType.StringType }),
                        ) { entry ->
                            val parentEntry = remember(entry) {
                                navController.getBackStackEntry(NavRoutes.BACKEND_SETTINGS)
                            }
                            val viewModel: ConfigViewModel = koinViewModel(viewModelStoreOwner = parentEntry)
                            ConfigSectionDetailScreen(
                                sectionKey = entry.arguments?.getString("sectionKey") ?: "",
                                onNavigateBack = { navController.popBackStack() },
                                viewModel = viewModel,
                            )
                        }
                    }
                    composable(
                        NavRoutes.APP_SETTINGS,
                        arguments = listOf(
                            navArgument("localOnly") {
                                type = NavType.BoolType
                                defaultValue = false
                            },
                        ),
                    ) {
                        AppSettingsScreen(
                            onNavigateBack = { navController.popBackStack() },
                        )
                    }
                    composable(NavRoutes.SETUP) {
                        SetupWizardScreen(
                            onExportDiagnostics = { navController.navigate(NavRoutes.DIAGNOSTICS) },
                            onSetupComplete = {
                                navController.navigate(NavRoutes.CHAT) {
                                    popUpTo(NavRoutes.CHAT) { inclusive = true }
                                }
                            },
                        )
                    }
                }
            }
        }
    }

    private fun requestNotificationPermissionIfNeeded() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            if (ContextCompat.checkSelfPermission(this, Manifest.permission.POST_NOTIFICATIONS)
                != PackageManager.PERMISSION_GRANTED
            ) {
                notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
            }
        }
    }
}

package io.clawdroid

import android.app.Application
import android.util.Log
import io.clawdroid.backend.api.BackendLifecycle
import io.clawdroid.backend.api.BackendState
import io.clawdroid.backend.api.GatewaySettingsStore
import io.clawdroid.backend.config.ConfigApiClient
import io.clawdroid.backend.config.configModule
import io.clawdroid.core.data.remote.WebSocketClient
import io.clawdroid.di.appModule
import io.clawdroid.di.flavorModule
import io.clawdroid.receiver.NotificationHelper
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.filter
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.launch
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.koin.android.ext.koin.androidContext
import org.koin.core.context.startKoin
import java.net.URLEncoder

class ClawDroidApp : Application() {
    override fun onCreate() {
        super.onCreate()
        io.clawdroid.diagnostics.DiagnosticEvents.initialize(this)
        val koinApp = startKoin {
            androidContext(this@ClawDroidApp)
            modules(appModule, flavorModule, configModule)
        }
        NotificationHelper.createNotificationChannel(this)

        val koin = koinApp.koin
        val backendLifecycle: BackendLifecycle = koin.get()
        val settingsStore: GatewaySettingsStore = koin.get()
        val wsClient: WebSocketClient = koin.get()
        val configApiClient: ConfigApiClient = koin.get()
        val scope: CoroutineScope = koin.get()
        scope.launch {
            wsClient.connectionState.collect { state ->
                val code = when (state) {
                    io.clawdroid.core.domain.model.ConnectionState.CONNECTED -> "connected"
                    io.clawdroid.core.domain.model.ConnectionState.DISCONNECTED -> "disconnected"
                    else -> "connection_started"
                }
                io.clawdroid.diagnostics.DiagnosticEvents.record("websocket", code)
            }
        }
        scope.launch { backendLifecycle.start() }
        scope.launch {
            // Wait for backend to be running before connecting WebSocket
            combine(
                settingsStore.settings
                    .map { it.httpPort to it.apiKey }
                    .distinctUntilChanged(),
                backendLifecycle.state,
            ) { settings, state -> settings to state }
                .filter { (_, state) -> state == BackendState.RUNNING }
                .map { (settings, _) -> settings }
                .distinctUntilChanged()
                .collect {
                    // Fetch WS connection info from config API
                    val wsUrl = fetchWsUrl(configApiClient)
                    if (wsClient.wsUrl != wsUrl) {
                        wsClient.disconnect()
                        wsClient.wsUrl = wsUrl
                        wsClient.connect()
                    }
                }
        }
    }

    private suspend fun fetchWsUrl(configApiClient: ConfigApiClient): String {
        return try {
            val cfg = configApiClient.getConfig()
            val ws = cfg["channels"]?.jsonObject?.get("websocket")?.jsonObject
            if (ws != null) {
                val host = ws["host"]?.jsonPrimitive?.content ?: "127.0.0.1"
                val port = ws["port"]?.jsonPrimitive?.content ?: "18793"
                val path = ws["path"]?.jsonPrimitive?.content ?: "/ws"
                val wsApiKey = ws["api_key"]?.jsonPrimitive?.content ?: ""
                buildString {
                    append("ws://$host:$port$path")
                    if (wsApiKey.isNotEmpty()) {
                        append("?api_key=${URLEncoder.encode(wsApiKey, "UTF-8")}")
                    }
                }
            } else {
                DEFAULT_WS_URL
            }
        } catch (e: Exception) {
            Log.w(TAG, "Failed to fetch WS config from API, using defaults", e)
            DEFAULT_WS_URL
        }
    }

    companion object {
        private const val TAG = "ClawDroidApp"
        private const val DEFAULT_WS_URL = "ws://127.0.0.1:18793/ws"
    }
}

