import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

@Composable
fun DiagnosticsExportScreen(onBack: () -> Unit) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    var busy by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    val save = rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/zip")) { uri ->
        if (uri != null) {
            busy = true
            scope.launch {
                try {
                    withContext(Dispatchers.IO) {
                        val archive = DiagnosticsExporter.create(context)
                        val stream = context.contentResolver.openOutputStream(uri)
                            ?: throw java.io.IOException("Output unavailable")
                        stream.use { output -> archive.inputStream().use { it.copyTo(output) } }
                    }
                    message = "Тестовый файл сохранён. Пришлите его вместе с описанием проблемы"
                } catch (error: kotlinx.coroutines.CancellationException) { throw error }
                catch (_: Exception) { message = "Не удалось сохранить файл. Выберите другую папку и повторите" }
                finally { busy = false }
            }
        }
    }
    Surface(Modifier.fillMaxSize()) {
        Column(Modifier.fillMaxSize().padding(24.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) {
            TextButton(onClick = onBack) { Text("Назад") }
            Text("Тестовый файл", style = MaterialTheme.typography.headlineMedium)
            Text("Архив содержит версию приложения, разрешения и последние 200 событий: подключение, действия, остановку и ошибки. Ключи, переписка и снимки экрана в него не входят.")
            Button(onClick = { message = null; save.launch("Jarvisjon-test-${System.currentTimeMillis()}.zip") }, enabled = !busy, modifier = Modifier.fillMaxWidth()) { Text(if (busy) "Сохранение…" else "Сохранить ZIP на телефон") }
            OutlinedButton(onClick = {
                message = null
                runCatching { DiagnosticsExporter.share(context) }.onFailure { message = "Не удалось отправить архив. Сохраните ZIP на телефон" }
            }, enabled = !busy, modifier = Modifier.fillMaxWidth()) { Text("Отправить ZIP") }
            message?.let { Text(it) }
        }
    }
}

package io.clawdroid.diagnostics

import org.junit.jupiter.api.Assertions.*
import org.junit.jupiter.api.Test

class DiagnosticEventsTest {
    @Test fun `diagnostics rejects arbitrary payload and invalid HTTP codes`() {
        assertThrows(IllegalArgumentException::class.java) { DiagnosticEvents.record("openai", "sk_secret") }
        assertThrows(IllegalArgumentException::class.java) { DiagnosticEvents.record("user_prompt", "started") }
        assertThrows(IllegalArgumentException::class.java) { DiagnosticEvents.record("openai", "network", 999) }
        assertThrows(IllegalArgumentException::class.java) { DiagnosticEvents.record("tool", "success", durationMs = -1) }
    }
    @Test fun `journal keeps only latest 200 structured events`() {
        repeat(205) { DiagnosticEvents.record("tool", "ui_success", durationMs = it.toLong()) }
        val events = DiagnosticEvents.snapshot()
        assertEquals(200, events.size)
        assertEquals(5L, events.first().durationMs)
        assertEquals(204L, events.last().durationMs)
    }
}

package io.clawdroid.setup

import org.junit.jupiter.api.Assertions.*
import org.junit.jupiter.api.Test

class OpenAiFailureTest {
    @Test fun `local auth differs from upstream key rejection`() {
        assertEquals("local_gateway_auth", OpenAiFailure.from(null, 401).code)
        assertEquals("authentication", OpenAiFailure.from("authentication", 401).code)
    }
    @Test fun `quota rate region permissions are actionable distinct categories`() {
        val codes = listOf("quota", "rate_limit", "region", "permission", "model", "network")
        assertEquals(codes.size, codes.map { OpenAiFailure.from(it, 403).message }.toSet().size)
        codes.forEach { assertEquals(it, OpenAiFailure.from(it, 403).code) }
    }
    @Test fun `unknown server content cannot become user message or event code`() {
        val failure = OpenAiFailure.from("sk-secret-user-content", 503)
        assertEquals("upstream", failure.code)
        assertFalse(failure.message.contains("secret"))
    }
}

package io.clawdroid.setup

import io.mockk.*
